void MainTest() {
  TestGroupBegin("上下电测试组", "验证 KL15 上电后信号初始化");
  TestCaseDescription("上电后 EngineSpeed 应为 0");

  // 步骤1：触发上电
  TestStep("发送 KL15 上电");
  @Power::KL15 = 1;
  testWaitForTimeout(300);

  // 步骤2：判定
  if ($EngineState::EngineSpeed == 0)
    TestStepPass("上电初始转速为 0，符合预期");
  else
    TestStepFail("上电初始转速非 0，异常");

  TestGroupEnd();
}
